    platform: args.platform === 'youtube' ? 'youtube' : args.platform === 'tiktok' ? 'tiktok' : 'instagram',
    accounts: Array.isArray(args.accounts) ? args.accounts.map((a) => String(a).slice(0, 120)) : [],
