  delete wf.captionUserEdited
  delete wf.captionError
  delete wf.recovery
  wf.captionPending = true
  touch(wf)
  void draftCaptionInto(id)
  return { ok: true }
}

/**
 * 캡션을 사용자가 직접 쓴다. `captionUserEdited` 를 세워 이후 늦게 도착하는 모델 응답이
