252	function parseMultipart(bodyBuf, boundary) {
253	  const boundaryBuf = Buffer.from(`--${boundary}`)
254	  const crlfcrlf = Buffer.from('\r\n\r\n')
255	  const parts = []
256	  let idx = bodyBuf.indexOf(boundaryBuf)
257	  while (idx !== -1) {
258	    const nextIdx = bodyBuf.indexOf(boundaryBuf, idx + boundaryBuf.length)
259	    if (nextIdx === -1) break
260	    let partStart = idx + boundaryBuf.length
261	    if (bodyBuf[partStart] === 0x0d && bodyBuf[partStart + 1] === 0x0a) partStart += 2
262	    let partEnd = nextIdx
263	    if (bodyBuf[partEnd - 2] === 0x0d && bodyBuf[partEnd - 1] === 0x0a) partEnd -= 2
264	    if (partEnd > partStart) parts.push(bodyBuf.subarray(partStart, partEnd))
265	    idx = nextIdx
266	  }
267	  const result = { fields: {}, files: {} }
268	  for (const part of parts) {
269	    const headerEnd = part.indexOf(crlfcrlf)
270	    if (headerEnd === -1) continue
271	    const headerStr = part.subarray(0, headerEnd).toString('utf8')
272	    const data = part.subarray(headerEnd + 4)
273	    const nameMatch = /name="([^"]*)"/.exec(headerStr)
274	    const filenameMatch = /filename="([^"]*)"/.exec(headerStr)
275	    const ctMatch = /Content-Type:\s*([^\r\n]+)/i.exec(headerStr)
276	    const name = nameMatch ? nameMatch[1] : ''
277	    if (!name) continue
278	    if (filenameMatch) {
279	      result.files[name] = {
280	        filename: filenameMatch[1],
281	        contentType: ctMatch ? ctMatch[1].trim() : 'application/octet-stream',
282	        data,
283	      }
284	    } else {
285	      result.fields[name] = data.toString('utf8')
286	    }
287	  }
288	  return result
289	}
