787	function ensureRealDomainCert(outDir) {
788	  const key = path.join(outDir, 'social-realmodel-key.pem')
789	  const cert = path.join(outDir, 'social-realmodel-cert.pem')
790	  if (fs.existsSync(key) && fs.existsSync(cert)) return { key, cert }
791	  fs.mkdirSync(outDir, { recursive: true })
792	  const r = spawnSync('openssl', [
793	    'req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '30',
794	    '-keyout', key, '-out', cert, '-subj', '/CN=social-realmodel-fixture',
795	  ], { encoding: 'utf8' })
796	  if (r.status !== 0 || !fs.existsSync(cert)) return null
797	  return { key, cert }
798	}
