890	async function handlePublishOnState(state, req, res) {
891	  const ct = req.headers['content-type'] || ''
892	  const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(ct)
893	  if (!boundaryMatch) return sendJson(res, 400, { error: 'multipart boundary 없음' })
894	  const boundary = boundaryMatch[1] || boundaryMatch[2]
895	  const bodyBuf = await readBodyBuffer(req)
896	  const parsed = parseMultipart(bodyBuf, boundary)
897	  const file = parsed.files['file']
898	  const caption = (parsed.fields['caption'] || '').trim()
899	  if (!file || !caption) return sendJson(res, 400, { error: '파일 또는 문구 누락' })
900	  const sha256 = crypto.createHash('sha256').update(file.data).digest('hex')
901	  const id = String(state.publishes.length + 1)
902	  state.publishes.push({ id, bytes: file.data.length, sha256, caption, at: Date.now(), viaHost: req.headers.host || '' })
