908	/**
909	 * `state`(startSocialFixtures 가 반환한 것과 **같은 객체**)를 공유하는 HTTPS 서버를 띄운다 —
910	 * `/state` 가 여기서 받은 게시도 그대로 반영한다(관측 지점을 하나로 유지).
911	 * `control` 은 **요청 시점에 읽는 가변 객체**다(하네스가 실행 중에 토글한다):
912	 *   - `control.holdPublish === true` 면 POST /sns/publish 를 **먼저 state 에 기록한 뒤 응답을 보내지
913	 *     않고 잡아 둔다**. 즉 "서버에는 글이 올라갔는데 브라우저는 성공 신호를 못 받은" 상태를 실제
914	 *     네트워크 수준에서 재현한다(앱 데이터 파일을 손으로 편집해 가짜 상태를 만드는 것이 아니다).
915	 *     잡아 둔 응답은 `releaseHeld()`(끊기) 또는 `close()` 가 정리한다.
916	 *   - 기록 시점은 `state.publishes` 길이로 **앱 밖에서** 관측된다(판정의 근거를 앱에 묻지 않는다).
917	 * @returns {Promise<{port:number, hostResolverRule:string, heldCount:() => number, releaseHeld:() => void, close:() => Promise<void>} | null>} 실패 시 null.
918	 */
919	export async function startInstagramHttpsFixture(state, outDir, control = {}) {
920	  const certPaths = ensureRealDomainCert(outDir)
921	  if (!certPaths) return null
922	
923	  /** 응답을 보내지 않고 붙잡아 둔 게시 요청들 — close()/releaseHeld() 가 정리한다. */
924	  const held = []
925	  function holdPublishResponse(req, res) {
926	    return readBodyBuffer(req).then((bodyBuf) => {
927	      const ct = req.headers['content-type'] || ''
928	      const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(ct)
929	      if (!boundaryMatch) return sendJson(res, 400, { error: 'multipart boundary 없음' })
930	      const parsed = parseMultipart(bodyBuf, boundaryMatch[1] || boundaryMatch[2])
931	      const file = parsed.files['file']
932	      const caption = (parsed.fields['caption'] || '').trim()
933	      if (!file || !caption) return sendJson(res, 400, { error: '파일 또는 문구 누락' })
934	      const sha256 = crypto.createHash('sha256').update(file.data).digest('hex')
935	      const id = String(state.publishes.length + 1)
936	      // ① 서버에는 실제로 저장된다(= 글이 올라갔다). ② 그런데 응답은 나가지 않는다(= 성공 신호 없음).
937	      state.publishes.push({ id, bytes: file.data.length, sha256, caption, at: Date.now(), viaHost: req.headers.host || '', heldResponse: true })
938	      held.push(res)
939	      return undefined   // 의도적으로 res 를 끝내지 않는다.
940	    })
941	  }
942	
943	  const server = https.createServer(
944	    { key: fs.readFileSync(certPaths.key), cert: fs.readFileSync(certPaths.cert) },
945	    (req, res) => {
946	      let urlObj
947	      try { urlObj = new URL(req.url, `https://${req.headers.host || REAL_DOMAIN_HOST}`) } catch { urlObj = null }
948	      const pathname = urlObj ? urlObj.pathname : req.url
949	      Promise.resolve().then(async () => {
950	        if (req.method === 'GET' && (pathname === '/' || pathname === '')) {
951	          return sendHtml(res, 200, instagramWizardHtml(state))
952	        }
953	        if (req.method === 'POST' && pathname === '/sns/publish') {
954	          if (control.holdPublish) return holdPublishResponse(req, res)
955	          return handlePublishOnState(state, req, res)
956	        }
957	        const postMatch = /^\/sns\/post\/(\w+)$/.exec(pathname)
958	        if (req.method === 'GET' && postMatch) {
959	          const rec = state.publishes.find((p) => p.id === postMatch[1])
960	          if (!rec) return sendHtml(res, 404, page('<p>게시물을 찾을 수 없습니다.</p>'))
961	          // 목록과 같은 모양(작성자·게시 시각 포함) — 상세로 들어가도 확인 근거를 읽을 수 있어야 한다.
962	          return sendHtml(res, 200, page(`<h1>게시물 #${escapeHtml(rec.id)}</h1>${publishedPostHtml(rec)}`))
963	        }
964	        return sendHtml(res, 404, page('<p>not found</p>'))
965	      }).catch((err) => {
966	        try { sendHtml(res, 500, page(`<p>fixture error: ${escapeHtml(err?.message)}</p>`)) } catch { /* ignore */ }
967	      })
968	    },
969	  )
970	  const [port] = await getFreePorts(1)
971	  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', resolve) })
972	  return {
973	    port,
974	    hostResolverRule: `MAP ${REAL_DOMAIN_HOST} 127.0.0.1:${port}`,
975	    heldCount: () => held.length,
976	    releaseHeld() {
977	      // 응답을 정상으로 바꿔주지 않는다 — 끊는다. "성공 신호를 끝내 못 받았다"가 이 시나리오의 전제다.
978	      for (const res of held.splice(0)) { try { res.destroy() } catch { /* ignore */ } }
979	    },
980	    async close() {
981	      for (const res of held.splice(0)) { try { res.destroy() } catch { /* ignore */ } }
982	      await closeServer(server)
983	    },
984	  }
985	}
