987	// 직접 실행하면 수동 확인용으로 URL 을 찍고 Ctrl+C 까지 살아 있는다.
988	// (process.argv[1] 이 없는 실행 환경 — 예: `node --input-type=module` 로 stdin 모듈 실행 — 에서는
989	// pathToFileURL(undefined) 가 예외를 던지므로 먼저 존재를 확인한다.)
990	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
991	  const fixture = await startSocialFixtures()
992	  console.log('[social-fixture] base    :', fixture.base)
993	  console.log('[social-fixture] altBase :', fixture.altBase)
994	  console.log('Ctrl+C 로 종료하세요.')
995	  process.on('SIGINT', async () => { await fixture.close(); process.exit(0) })
