    // 나갈 수 있으므로 거둔다(사용자는 다시 확인하면 된다).
    delete wf.promotedAt
    touch(wf)
    return { ok: false, error: r.error ?? '게시를 시작하지 못했습니다.', errorEn: r.error ?? 'Failed to start publishing.' }
  }
