1411	    wf.priorReceipts = [...(wf.priorReceipts ?? []), prior].slice(-MAX_PRIOR_RECEIPTS)
1412	    delete wf.receipt
1413	  }
1414	  // 옛 초안 게시 작업은 **지우지 않는다** — ai-tasks.json 에 그대로 남아 감사 추적이 된다.
1415	  // 여기서는 이 워크플로의 "현재 게시 작업" 자리만 비운다(새 작업이 들어올 자리).
1416	  delete wf.taskIds.publish
1417	  delete wf.error
1418	  delete wf.recovery
1419	  delete wf.uncertaintyResolvedFor
1420	  // 이 한 건을 올린다는 사실. params.mode 는 건드리지 않는다(자동 게시로 번지지 않게).
1421	  wf.promotedAt = Date.now()
1422	  touch(wf)
1423	
1424	  // 기존 게시 경로를 그대로 탄다 — 게이트·내구성 경계·이어가기 보호를 재사용한다.
1425	  const r = runPublishStage(wf, subject.genTaskId, subject.artifactId)
1426	  if (!r.ok) {
1427	    // 시작조차 못 했다 = 아무것도 나가지 않았다. 승인 사실을 남겨 두면 다음 클릭이 확인 없이
1428	    // 나갈 수 있으므로 거둔다(사용자는 다시 확인하면 된다).
1429	    delete wf.promotedAt
1430	    touch(wf)
1431	    return { ok: false, error: r.error ?? '게시를 시작하지 못했습니다.', errorEn: r.error ?? 'Failed to start publishing.' }
1432	  }
1433	  return { ok: true }
1434	}
1435	
1436	/**
1437	 * 이 워크플로가 **지금** 실제로 게시하는가. 처음 고른 모드(params.mode)에, 사용자가 나중에 초안을
1438	 * 올리겠다고 확정한 사실(promotedAt)을 더한 값이다. 게시 작업을 만들 때와 영수증을 적을 때 **둘 다**
1439	 * 이 함수를 써야 한다 — 한쪽만 쓰면 실제로는 게시했는데 영수증이 "초안" 이라고 적히는 식으로 어긋난다.

