498	export function AiSocialPanel({
499	  windowId, activeId, isInternal, providerReady,
500	}: {
501	  windowId: string
502	  activeId: string | undefined
503	  isInternal: boolean
504	  providerReady: boolean
505	}) {
506	  const [view, setView] = useState<'generate' | 'engage'>('generate')
507	
508	  // ===== 뷰1: 이미지 만들어 올리기 =====
509	  const [genService, setGenService] = useState<SocialService>('genspark')
510	  const [customUrl, setCustomUrl] = useState('')
511	  const [prompt, setPrompt] = useState('')
512	  const [genPlatform, setGenPlatform] = useState<SocialPlatform>('instagram')
513	  const [genAccount, setGenAccount] = useState('')
514	  const [tone, setTone] = useState('')
515	  const [tags, setTags] = useState('')
516	  const [genMode, setGenMode] = useState<SocialMode>('draft')
517	  // 자동 게시 선승인 — 기본은 꺼짐. 사용자가 이 작업을 시작할 때 직접 켠 경우에만 적용된다.
518	  const [autoPublish, setAutoPublish] = useState(false)
519	  const [autoMaxPosts, setAutoMaxPosts] = useState(1)
520	  const [autoMinutes, setAutoMinutes] = useState(30)
521	  const [grantInfo, setGrantInfo] = useState<AutoPublishGrantView | null>(null)
522	  const refreshGrant = () => { void window.browserAPI.ai.socialGrantGet().then(setGrantInfo) }
523	  const [genBusy, setGenBusy] = useState(false)
524	  const [genError, setGenError] = useState<string | null>(null)
525	
526	  const [workflows, setWorkflows] = useState<SocialWorkflow[]>([])
527	  const [candidates, setCandidates] = useState<Record<string, Array<{ meta: ArtifactMeta; dataUrl: string | null }>>>({})
528	  const [previewData, setPreviewData] = useState<Record<string, string | null>>({})
529	  const [captionDrafts, setCaptionDrafts] = useState<Record<string, string>>({})
530	  const captionSeededRef = useRef<Set<string>>(new Set())
531	  // 초안 승격("이 초안을 게시하기") — 워크플로 id 별로 열린 확정 패널·오류·진행중 여부를 든다.
532	  const [promotions, setPromotions] = useState<Record<string, AiPromotionPlan>>({})
533	  const [promoteErrors, setPromoteErrors] = useState<Record<string, { error: string; errorEn: string }>>({})
534	  const [promoteBusyIds, setPromoteBusyIds] = useState<Record<string, boolean>>({})
535	
536	  useEffect(() => {
537	    void window.browserAPI.ai.socialList().then(setWorkflows)
538	    const off = window.browserAPI.ai.onSocialChanged((list) => setWorkflows(list))
539	    return off
540	  }, [])
541	
542	  // 생성 후보(여러 장 나올 수 있는 경우) 썸네일 — 아직 못 받았으면 다시 시도, 받았으면 멈춘다.
543	  useEffect(() => {
544	    for (const w of workflows) {
545	      if (w.stage !== 'generate' || w.artifactId || !w.taskIds.generate) continue
546	      const already = candidates[w.id]
547	      if (already && already.length) continue
548	      const tid = w.taskIds.generate
549	      void window.browserAPI.ai.artifactList(tid).then(async (list) => {
550	        if (!list.length) return
551	        const items = await Promise.all(list.map(async (m) => ({
552	          meta: m as ArtifactMeta,
553	          dataUrl: (await window.browserAPI.ai.artifactData(tid, m.id))?.dataUrl ?? null,
554	        })))
555	        setCandidates((prev) => ({ ...prev, [w.id]: items }))
556	      })
557	    }
558	    // eslint-disable-next-line react-hooks/exhaustive-deps
559	  }, [workflows, candidates])
560	
561	  // 확정된 이미지 미리보기(캡션 확인 단계 이후) — 한 번만 받아 캐시.
562	  useEffect(() => {
563	    for (const w of workflows) {
564	      if (!w.artifactId || !w.taskIds.generate) continue
565	      if (w.id in previewData) continue
566	      const tid = w.taskIds.generate
567	      const aid = w.artifactId
568	      void window.browserAPI.ai.artifactData(tid, aid).then((r) => {
569	        setPreviewData((prev) => ({ ...prev, [w.id]: r?.dataUrl ?? null }))
570	      })
571	    }
572	    // eslint-disable-next-line react-hooks/exhaustive-deps
573	  }, [workflows, previewData])
574	
575	  // 캡션 초안 — review 단계에 처음 들어설 때만 백엔드 값으로 시드(그 뒤엔 사용자 편집을 덮어쓰지 않음).
576	  useEffect(() => {
577	    for (const w of workflows) {
578	      if (w.stage === 'review' && !captionSeededRef.current.has(w.id)) {
579	        captionSeededRef.current.add(w.id)
580	        setCaptionDrafts((prev) => ({ ...prev, [w.id]: w.caption ?? '' }))
581	      }
582	    }
583	  }, [workflows])
584	
585	  // 열린 확정 패널이 낡아지면(승격됐거나, 계획을 딸 때의 단계에서 벗어났으면) 자동으로 닫는다 —
586	  // 사용자가 이미 처리된(혹은 더는 유효하지 않은) 계획을 보며 게시 확정을 누르는 일을 막는다.
587	  useEffect(() => {
588	    setPromotions((prev) => {
589	      if (Object.keys(prev).length === 0) return prev
590	      let changed = false
591	      const next = { ...prev }
592	      for (const w of workflows) {
593	        const plan = next[w.id]
594	        if (!plan) continue
595	        const expectedStage: SocialStage = plan.source === 'review' ? 'review' : 'done'
596	        if (w.promotedAt || w.stage !== expectedStage) {
597	          delete next[w.id]
598	          changed = true
599	        }
600	      }
601	      return changed ? next : prev
602	    })
603	  }, [workflows])
604	
605	  const requestPromote = async (id: string) => {
606	    setPromoteErrors((prev) => {
607	      if (!(id in prev)) return prev
608	      const next = { ...prev }; delete next[id]; return next
609	    })
610	    const r: AiPromotePrepareResult = await window.browserAPI.ai.socialPromotePrepare(id)
611	    if (!r.ok) {
612	      setPromoteErrors((prev) => ({ ...prev, [id]: { error: r.error, errorEn: r.errorEn } }))
613	      return
614	    }
615	    setPromotions((prev) => ({ ...prev, [id]: r.plan }))
616	  }
617	  const cancelPromote = (id: string) => {
618	    setPromotions((prev) => {
619	      if (!(id in prev)) return prev
620	      const next = { ...prev }; delete next[id]; return next
621	    })
622	    void window.browserAPI.ai.socialPromoteCancel(id)
623	  }
624	  const confirmPromote = async (id: string) => {
625	    const plan = promotions[id]
626	    if (!plan) return
627	    setPromoteBusyIds((prev) => ({ ...prev, [id]: true }))
628	    try {
629	      const r = await window.browserAPI.ai.socialPromoteConfirm(id, plan.token)
630	      setPromotions((prev) => {
631	        if (!(id in prev)) return prev
632	        const next = { ...prev }; delete next[id]; return next
633	      })
634	      // 토큰이 이미 무효라 실패했을 수 있으므로, 같은 패널을 다시 열어 두지 않는다 —
635	      // 다시 시도하려면 승격 버튼을 눌러 새 확정을 받아야 한다.
636	      if (!r.ok) {
637	        setPromoteErrors((prev) => ({
638	          ...prev,
639	          [id]: { error: r.error || '게시를 확정하지 못했습니다.', errorEn: r.errorEn || 'Could not confirm the publish.' },
640	        }))
641	      }
642	    } finally {
643	      setPromoteBusyIds((prev) => {
644	        if (!(id in prev)) return prev
645	        const next = { ...prev }; delete next[id]; return next
646	      })
647	    }
648	  }
649	
650	  const startGenerate = async () => {
651	    if (!activeId || genBusy || !prompt.trim()) return
652	    if (genService === 'custom' && !customUrl.trim()) { setGenError('직접 입력할 생성 서비스 URL을 입력하세요.'); return }
653	    setGenBusy(true); setGenError(null)
654	    try {
655	      // 선승인은 **작업을 만들기 전에** 등록한다 — 작업이 선승인보다 먼저 생기면 범위 밖으로 판정돼
656	      // 자동 게시가 되지 않는다(메인의 createdAt 비교 규칙).
657	      if (genMode === 'publish' && autoPublish) {
658	        const g = await window.browserAPI.ai.socialGrant({
659	          platform: genPlatform,
660	          accounts: [genAccount.trim() || 'default'],
661	          maxPosts: autoMaxPosts,
662	          minutes: autoMinutes,
663	        })
664	        setGrantInfo(g)
665	        if (!g) { setGenError('자동 게시 선승인을 등록하지 못했습니다 — 확인 후 게시로 진행합니다.'); }
666	      }
667	      const params = {
668	        service: genService,
669	        customUrl: genService === 'custom' ? customUrl.trim() : undefined,
670	        prompt: prompt.trim(),
671	        platform: genPlatform,
672	        account: genAccount.trim() || undefined,
673	        tone: tone.trim() || undefined,
674	        tags: tags.split(',').map((s) => s.trim()).filter(Boolean),
675	        mode: genMode,
676	        windowId,
677	        tabId: activeId,
678	      }
679	      const w = await window.browserAPI.ai.socialStart(params)

