// 초안 승격(draft promotion) **게이트 판정** 검증 — 앱 없이 도는 순수 검사.
//
// 무엇을 지키는가: "만들어 둔 초안을 다시 만들지 않고 게시로 올린다" 는 편의 기능이지만, 그 끝에
// 있는 것은 **되돌릴 수 없는 외부 게시**다. 그래서 이 판정이 지켜야 하는 것은 둘이다.
//
//   ① 올려도 되는 것만 올린다 — 이미 게시된 것·게시 중인 것·나갔는지 모르는 것·계정이 없는 것·
//      이미지가 사라진 것은 거부한다.
//   ② 사용자가 **확인한 그것**만 올린다 — 확인 뒤에 캡션·계정·이미지가 바뀌었으면 그 확인은 무효다.
//      확인은 1회용이라 연타·재전송으로 두 번 나가지 않는다.
//
// 이 파일이 보증하는 것: 위 판정 규칙(거부 경로 전부 + 확인의 바인딩·1회용).
// 이 파일이 보증하지 **않는** 것: 실제 게시 흐름(작업 생성·산출물 복사·업로드·영수증). 그것은
//   build/verify-draft-promotion-cdp.mjs 가 실제 앱 + 실제 UI 클릭 + 로컬 픽스처로 검증한다.
//   여기서는 **성공 경로의 confirm 을 일부러 부르지 않는다** — 부르면 실제 게시 단계가 시작된다.
//
// 선례: build/verify-auto-publish.mjs (같은 electron 스텁 방식 · 같은 양방향 판정 원칙).

import path from 'node:path'
import fs from 'node:fs'
import os from 'node:os'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const require = createRequire(import.meta.url)
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-promote-'))

// social-workflow 는 electron(app) 과 설정을 끌어온다 — 파일 경로만 임시 디렉터리로 돌려주면 충분하다.
const Module = require('module')
const origLoad = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return {
      app: {
        getPath: () => root,
        getVersion: () => '0.0.0-test',
        getName: () => 'ezbrowser-test',
        on: () => {}, whenReady: () => Promise.resolve(), isPackaged: false,
      },
      ipcMain: { handle: () => {}, on: () => {} },
      safeStorage: { isEncryptionAvailable: () => false },
    }
  }
  return origLoad.call(this, req, ...rest)
}

const W = require(path.join(REPO, 'app/dist/main/features/ai/social-workflow.js'))
const A = require(path.join(REPO, 'app/dist/main/features/ai/artifacts.js'))

let pass = 0, fail = 0
const results = []
const t = (name, cond, detail = '') => {
  if (cond) { pass++; console.log('  PASS', name) } else { fail++; console.log('  FAIL', name, detail) }
  results.push({ name, ok: !!cond, detail: cond ? '' : String(detail).slice(0, 400) })
}

/** 거부는 **한국어와 영어를 함께** 줘야 한다(화면이 둘 다 보인다). 통과 여부와 같이 본다. */
const rejected = (r, koNeedle, enNeedle) =>
  r && r.ok === false
  && typeof r.error === 'string' && r.error.includes(koNeedle)
  && typeof r.errorEn === 'string' && r.errorEn.toLowerCase().includes(enNeedle.toLowerCase())

// ───────────────────────── 진짜 산출물 만들기 ─────────────────────────
// 1×1 PNG — importDownloadedFile 이 이미지 매직바이트를 확인하므로 진짜 PNG 여야 한다.
const PNG_1X1 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64')

const GEN_TASK = 'task_gen_promotion'
const tmpPng = path.join(root, 'seed.png')
fs.writeFileSync(tmpPng, PNG_1X1)
const imported = A.importDownloadedFile({
  taskId: GEN_TASK, filePath: tmpPng,
  sourceUrl: 'http://127.0.0.1/gen.png', sourcePageUrl: 'http://127.0.0.1/gen', sourceTabId: 'tab1',
  expect: 'image', label: '테스트 산출물',
})
if (!imported.ok || !imported.meta) {
  console.error('FATAL: 테스트 산출물을 만들지 못했습니다 —', imported.error ?? imported.code)
  process.exit(2)
}
const ART = imported.meta

// ───────────────────────── 워크플로 시드 ─────────────────────────
// 저장 파일을 직접 써 두고 initSocialWorkflows 로 읽힌다(하네스 관례: 실제 복원 경로를 지난다).
const WF_FILE = path.join(root, 'ai-social-workflows.json')

function wf(over = {}) {
  const now = Date.now()
  return {
    id: over.id ?? 'wf1',
    params: {
      service: 'genspark', platform: 'instagram', prompt: '테스트 프롬프트',
      mode: 'draft', tabId: 'tab1', windowId: 'win1', account: 'me',
      ...(over.params ?? {}),
    },
    stage: over.stage ?? 'review',
    taskIds: over.taskIds ?? { generate: GEN_TASK },
    artifactId: 'artifactId' in over ? over.artifactId : ART.id,
    artifactPreview: 'artifactPreview' in over ? over.artifactPreview
      : { bytes: ART.bytes, format: ART.format, sha256: ART.sha256 },
    caption: 'caption' in over ? over.caption : '오늘의 사진입니다',
    createdAt: now - 1000, updatedAt: now - 1000,
    ...Object.fromEntries(Object.entries(over).filter(([k]) =>
      !['id', 'params', 'stage', 'taskIds', 'artifactId', 'artifactPreview', 'caption'].includes(k))),
  }
}

/** 워크플로 목록을 통째로 갈아 끼우고 저장소를 다시 읽힌다. */
function seed(list) {
  fs.writeFileSync(WF_FILE, JSON.stringify({ version: 1, workflows: list, grant: null }), 'utf8')
  W.initSocialWorkflows()
}

// ===================== ① 정상 초안은 확인 화면이 열린다 =====================

seed([wf()])
const p1 = W.preparePromotion('wf1')
t('확인 단계 초안이면 확정 화면이 열린다', p1.ok === true, JSON.stringify(p1).slice(0, 300))
t('확정 화면이 보여 주는 이미지 지문이 **실제 보관 파일의 sha256** 과 같다',
  p1.ok && p1.plan.artifactSha256 === ART.sha256, `plan=${p1.ok ? p1.plan.artifactSha256 : 'n/a'} art=${ART.sha256}`)
t('확정 화면이 목적지·계정·캡션을 그대로 보여 준다',
  p1.ok && p1.plan.platform === 'instagram' && p1.plan.account === 'me' && p1.plan.caption === '오늘의 사진입니다',
  JSON.stringify(p1.ok ? p1.plan : {}).slice(0, 300))
t('확정 화면에 한국어·영어 플랫폼 이름이 함께 있다',
  p1.ok && !!p1.plan.platformLabel && !!p1.plan.platformLabelEn && p1.plan.platformLabel !== p1.plan.platformLabelEn,
  JSON.stringify(p1.ok ? [p1.plan.platformLabel, p1.plan.platformLabelEn] : []))
t('확정 화면을 여는 것만으로는 승격이 기록되지 않는다(디스크·메모리 둘 다)',
  !W.getWorkflow('wf1').promotedAt && !JSON.parse(fs.readFileSync(WF_FILE, 'utf8')).workflows[0].promotedAt)

// 취소는 **아무것도 바꾸지 않는다**.
const beforeCancel = JSON.stringify(W.getWorkflow('wf1'))
W.cancelPromotion('wf1')
t('취소하면 워크플로가 한 글자도 바뀌지 않는다', JSON.stringify(W.getWorkflow('wf1')) === beforeCancel)
t('취소한 뒤에는 그 확인으로 게시할 수 없다',
  rejected(W.confirmPromotion('wf1', p1.ok ? p1.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))

// ===================== ② 확인은 1회용이다 =====================

seed([wf()])
const p2 = W.preparePromotion('wf1')
t('틀린 토큰으로는 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', 'wrong-token'), '확인 정보가 맞지 않아', 'did not match'))
t('틀린 토큰 한 번으로 그 확인은 소진된다 — 곧이어 맞는 토큰을 보내도 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', p2.ok ? p2.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))
t('그 사이에도 승격 기록은 생기지 않았다', !W.getWorkflow('wf1').promotedAt)

// 만료
seed([wf()])
const p2b = W.preparePromotion('wf1')
t('오래된 확인은 만료된다',
  (() => {
    const realNow = Date.now
    Date.now = () => realNow() + 11 * 60_000   // TTL 10분
    try { return rejected(W.confirmPromotion('wf1', p2b.ok ? p2b.plan.token : 'x'), '만료', 'expired') }
    finally { Date.now = realNow }
  })())

// ===================== ③ 확인한 것과 달라지면 무효다 =====================

seed([wf()])
const p3 = W.preparePromotion('wf1')
W.setCaption('wf1', '완전히 다른 캡션')
const r3 = W.confirmPromotion('wf1', p3.ok ? p3.plan.token : 'x')
t('확인 뒤 캡션이 바뀌면 그 확인으로 게시하지 않는다', r3.ok === false, JSON.stringify(r3).slice(0, 300))
t('바뀐 것이 캡션이라고 사람 말로 알려 준다(ko·en)',
  typeof r3.error === 'string' && r3.error.includes('캡션')
  && typeof r3.errorEn === 'string' && r3.errorEn.includes('caption'),
  JSON.stringify(r3).slice(0, 300))
t('캡션을 바꾼 것만으로 게시가 나가지 않았다', !W.getWorkflow('wf1').promotedAt && !W.getWorkflow('wf1').taskIds.publish)

seed([wf()])
const p4 = W.preparePromotion('wf1')
W.setWorkflowAccount('wf1', 'someone-else')
const r4 = W.confirmPromotion('wf1', p4.ok ? p4.plan.token : 'x')
t('확인 뒤 계정이 바뀌면 그 확인으로 게시하지 않는다', r4.ok === false, JSON.stringify(r4).slice(0, 300))
t('바뀐 것이 계정이라고 사람 말로 알려 준다(ko·en)',
  typeof r4.error === 'string' && r4.error.includes('계정')
  && typeof r4.errorEn === 'string' && r4.errorEn.includes('account'),
  JSON.stringify(r4).slice(0, 300))

// 바인딩 지문 자체가 그 사실들로 갈리는가 — 같은 내용이면 같고, 한 글자만 달라도 다르다.
seed([wf()])
const revA = W.preparePromotion('wf1').plan.revision
seed([wf()])
const revA2 = W.preparePromotion('wf1').plan.revision
seed([wf({ caption: '오늘의 사진입니다!' })])
const revB = W.preparePromotion('wf1').plan.revision
seed([wf({ params: { account: 'other' } })])
const revC = W.preparePromotion('wf1').plan.revision
t('같은 내용이면 바인딩 지문이 같고, 캡션·계정이 다르면 달라진다',
  revA === revA2 && revA !== revB && revA !== revC && revB !== revC,
  `A=${revA.slice(0, 8)} A2=${revA2.slice(0, 8)} B=${revB.slice(0, 8)} C=${revC.slice(0, 8)}`)

// ===================== ④ 올리면 안 되는 것은 거부한다 =====================

const denied = [
  ['계정이 없으면 거부한다', wf({ params: { account: undefined } }), '계정이 비어 있습니다', 'No account'],
  ['캡션이 비어 있으면 거부한다', wf({ caption: '   ' }), '캡션이 비어 있습니다', 'caption is empty'],
  ['캡션을 쓰는 중이면 거부한다', wf({ captionPending: true }), '캡션을 쓰는 중', 'still being drafted'],
  ['캡션 생성이 실패한 상태면 거부한다', wf({ captionError: '실패' }), '캡션을 만들지 못한', 'failed to generate'],
  ['처음부터 게시 모드였던 작업은 이 경로로 올리지 않는다', wf({ params: { mode: 'publish' } }), '초안이 아니라', 'publish mode'],
  ['이미 승격한 초안은 다시 올리지 않는다', wf({ promotedAt: Date.now() - 1 }), '이미 게시로 올린 초안', 'already been promoted'],
  ['게시 여부가 불확실하면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, publishUncertain: true, taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['게시 여부 확인 작업이 도는 중이면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, verifyTaskId: 'task_verify', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['생성 중인 작업은 거부한다', wf({ stage: 'generate' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['게시 중인 작업은 거부한다', wf({ stage: 'publish', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['실패한 작업은 거부한다', wf({ stage: 'failed' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['취소된 작업은 거부한다', wf({ stage: 'cancelled' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['이미 실제로 게시된 작업은 거부한다', wf({ stage: 'done', receipt: { status: 'verified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed a real publication'],
  ['사용자가 "이미 게시됨" 으로 결론 낸 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'user-confirmed', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['게시 여부 미확인으로 끝난 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'unverified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['status 가 없는 예전 영수증은 초안으로 치지 않는다(fail-closed)', wf({ stage: 'done', receipt: { evidence: '초안까지 준비(게시 안 함)', at: 1 } }), '예전 판본이라', 'predates'],
  ['지난 기록에 실제 게시가 있으면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 2 }, priorReceipts: [{ status: 'verified', at: 1 }] }), '이미 실제 게시 기록', 'already has a real publication'],
  ['보관 이미지가 없으면 거부한다', wf({ artifactId: 'art_doesnotexist' }), '보관된 이미지 파일을 찾을 수 없습니다', 'stored image file is gone'],
  ['생성 작업 기록이 없으면 거부한다', wf({ taskIds: {} }), '올릴 이미지 기록이 없습니다', 'No stored image'],
  ['보관 이미지가 처음 확인한 것과 다르면 거부한다', wf({ artifactPreview: { bytes: 1, format: 'png', sha256: 'deadbeef' } }), '처음 확인한 것과 달라졌습니다', 'no longer matches'],
]

for (const [name, record, ko, en] of denied) {
  seed([record])
  const pr = W.preparePromotion(record.id ?? 'wf1')
  const cf = W.confirmPromotion(record.id ?? 'wf1', 'any-token')
  // prepare 가 거부하고, 확인 화면을 건너뛰고 직접 confirm 을 불러도 거부한다(UI 를 믿지 않는다).
  t(name, rejected(pr, ko, en) && cf.ok === false, `prepare=${JSON.stringify(pr).slice(0, 220)} confirm=${JSON.stringify(cf).slice(0, 160)}`)
  // 거부는 **초안을 잃지 않는다** — 캡션·이미지·단계가 그대로 남아야 사용자가 고쳐서 다시 쓴다.
  const after = W.getWorkflow(record.id ?? 'wf1')
  t(`  └ 거부해도 초안이 그대로 남는다 — ${name}`,
    !!after && after.stage === record.stage && after.caption === record.caption
    && after.artifactId === record.artifactId && !after.promotedAt,
    JSON.stringify(after ?? {}).slice(0, 200))
}

// ===================== ⑤ 완료된 초안은 올릴 수 있다 =====================

seed([wf({
  stage: 'done',
  taskIds: { generate: GEN_TASK, publish: 'task_pub_draft' },
  receipt: { status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 1234 },
})])
const p5 = W.preparePromotion('wf1')
t('완료된 초안(영수증 status=draft)은 확정 화면이 열린다', p5.ok === true, JSON.stringify(p5).slice(0, 300))
t('그 확정 화면은 "완료된 초안에서 올린다" 고 표시한다', p5.ok && p5.plan.source === 'completed-draft', p5.ok ? p5.plan.source : 'n/a')

// ===================== ⑥ 승격 작업은 자동 게시 대상이 아니다 =====================

const g = W.grantAutoPublish({ platform: 'instagram', accounts: ['me'], maxPosts: 5, minutes: 60 })
t('선승인 자체는 만들어진다(대조군)', !!g)
const promoted = wf({ params: { mode: 'publish' }, promotedAt: Date.now(), createdAt: Date.now() })
promoted.createdAt = Date.now() + 1000   // 선승인보다 나중에 만들어진 것으로
const verdict = W.autoPublishVerdict(promoted)
t('사용자가 직접 확정해 올린 초안은 선승인이 있어도 자동 게시되지 않는다',
  verdict.ok === false && verdict.why.includes('직접 확정'), JSON.stringify(verdict))
W.revokeAutoPublish()

// ===================== ⑦ 재시작을 넘겨 기억한다 =====================

const priors = [{ status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 111, taskId: 'task_pub_draft', note: '초안 준비 기록' }]
seed([wf({ stage: 'done', promotedAt: 4242, priorReceipts: priors, receipt: { status: 'verified', at: 999 } })])
const restored = W.getWorkflow('wf1')
t('승격 사실이 재시작을 넘겨 남는다', restored.promotedAt === 4242, String(restored.promotedAt))
t('지난 초안 기록이 재시작을 넘겨 그대로 남는다',
  restored.priorReceipts?.length === 1 && restored.priorReceipts[0].status === 'draft'
  && restored.priorReceipts[0].at === 111 && restored.priorReceipts[0].taskId === 'task_pub_draft',
  JSON.stringify(restored.priorReceipts))

// 손상된 값 — **잊는 쪽이 위험하다**(잊으면 실제 게시가 "초안" 으로 적히고 또 올릴 수 있게 된다).
seed([wf({ stage: 'done', promotedAt: 'garbage', receipt: { status: 'verified', at: 1 } })])
t('승격 값이 손상돼도 "승격했다" 로 기억한다(fail-closed)', W.getWorkflow('wf1').promotedAt === 1,
  String(W.getWorkflow('wf1').promotedAt))
seed([wf({ stage: 'done', priorReceipts: 'not-an-array', receipt: { status: 'draft', at: 1 } })])
t('지난 기록이 손상됐으면 조용히 버리고 워크플로 자체는 살린다',
  !!W.getWorkflow('wf1') && !W.getWorkflow('wf1').priorReceipts)

// ===================== 마무리 =====================

const outDir = path.join(REPO, 'verify-out', 'draft-promotion-pure')
fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, 'results.json'),
  JSON.stringify({ at: new Date().toISOString(), pass, fail, results }, null, 2), 'utf8')

try { fs.rmSync(root, { recursive: true, force: true }) } catch { /* 임시 디렉터리 정리 실패는 무시 */ }

console.log(`\n초안 승격 게이트: ${pass} PASS / ${fail} FAIL`)
console.log('범위: 판정 규칙만(앱 없이). 실제 게시 흐름은 build/verify-draft-promotion-cdp.mjs 가 본다.')
process.exit(fail === 0 ? 0 : 1)

toolu_016F8drACDPhZ4BJ9pz7HcrA.content:
// 초안 승격(draft promotion) **게이트 판정** 검증 — 앱 없이 도는 순수 검사.
//
// 무엇을 지키는가: "만들어 둔 초안을 다시 만들지 않고 게시로 올린다" 는 편의 기능이지만, 그 끝에
// 있는 것은 **되돌릴 수 없는 외부 게시**다. 그래서 이 판정이 지켜야 하는 것은 둘이다.
//
//   ① 올려도 되는 것만 올린다 — 이미 게시된 것·게시 중인 것·나갔는지 모르는 것·계정이 없는 것·
//      이미지가 사라진 것은 거부한다.
//   ② 사용자가 **확인한 그것**만 올린다 — 확인 뒤에 캡션·계정·이미지가 바뀌었으면 그 확인은 무효다.
//      확인은 1회용이라 연타·재전송으로 두 번 나가지 않는다.
//
// 이 파일이 보증하는 것: 위 판정 규칙(거부 경로 전부 + 확인의 바인딩·1회용).
// 이 파일이 보증하지 **않는** 것: 실제 게시 흐름(작업 생성·산출물 복사·업로드·영수증). 그것은
//   build/verify-draft-promotion-cdp.mjs 가 실제 앱 + 실제 UI 클릭 + 로컬 픽스처로 검증한다.
//   여기서는 **성공 경로의 confirm 을 일부러 부르지 않는다** — 부르면 실제 게시 단계가 시작된다.
//
// 선례: build/verify-auto-publish.mjs (같은 electron 스텁 방식 · 같은 양방향 판정 원칙).

import path from 'node:path'
import fs from 'node:fs'
import os from 'node:os'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const require = createRequire(import.meta.url)
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-promote-'))

// social-workflow 는 electron(app) 과 설정을 끌어온다 — 파일 경로만 임시 디렉터리로 돌려주면 충분하다.
const Module = require('module')
const origLoad = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return {
      app: {
        getPath: () => root,
        getVersion: () => '0.0.0-test',
        getName: () => 'ezbrowser-test',
        on: () => {}, whenReady: () => Promise.resolve(), isPackaged: false,
      },
      ipcMain: { handle: () => {}, on: () => {} },
      safeStorage: { isEncryptionAvailable: () => false },
    }
  }
  return origLoad.call(this, req, ...rest)
}

const W = require(path.join(REPO, 'app/dist/main/features/ai/social-workflow.js'))
const A = require(path.join(REPO, 'app/dist/main/features/ai/artifacts.js'))

let pass = 0, fail = 0
const results = []
const t = (name, cond, detail = '') => {
  if (cond) { pass++; console.log('  PASS', name) } else { fail++; console.log('  FAIL', name, detail) }
  results.push({ name, ok: !!cond, detail: cond ? '' : String(detail).slice(0, 400) })
}

/** 거부는 **한국어와 영어를 함께** 줘야 한다(화면이 둘 다 보인다). 통과 여부와 같이 본다. */
const rejected = (r, koNeedle, enNeedle) =>
  r && r.ok === false
  && typeof r.error === 'string' && r.error.includes(koNeedle)
  && typeof r.errorEn === 'string' && r.errorEn.toLowerCase().includes(enNeedle.toLowerCase())

// ───────────────────────── 진짜 산출물 만들기 ─────────────────────────
// 1×1 PNG — importDownloadedFile 이 이미지 매직바이트를 확인하므로 진짜 PNG 여야 한다.
const PNG_1X1 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64')

const GEN_TASK = 'task_gen_promotion'
const tmpPng = path.join(root, 'seed.png')
fs.writeFileSync(tmpPng, PNG_1X1)
const imported = A.importDownloadedFile({
  taskId: GEN_TASK, filePath: tmpPng,
  sourceUrl: 'http://127.0.0.1/gen.png', sourcePageUrl: 'http://127.0.0.1/gen', sourceTabId: 'tab1',
  expect: 'image', label: '테스트 산출물',
})
if (!imported.ok || !imported.meta) {
  console.error('FATAL: 테스트 산출물을 만들지 못했습니다 —', imported.error ?? imported.code)
  process.exit(2)
}
const ART = imported.meta

// ───────────────────────── 워크플로 시드 ─────────────────────────
// 저장 파일을 직접 써 두고 initSocialWorkflows 로 읽힌다(하네스 관례: 실제 복원 경로를 지난다).
const WF_FILE = path.join(root, 'ai-social-workflows.json')

function wf(over = {}) {
  const now = Date.now()
  return {
    id: over.id ?? 'wf1',
    params: {
      service: 'genspark', platform: 'instagram', prompt: '테스트 프롬프트',
      mode: 'draft', tabId: 'tab1', windowId: 'win1', account: 'me',
      ...(over.params ?? {}),
    },
    stage: over.stage ?? 'review',
    taskIds: over.taskIds ?? { generate: GEN_TASK },
    artifactId: 'artifactId' in over ? over.artifactId : ART.id,
    artifactPreview: 'artifactPreview' in over ? over.artifactPreview
      : { bytes: ART.bytes, format: ART.format, sha256: ART.sha256 },
    caption: 'caption' in over ? over.caption : '오늘의 사진입니다',
    createdAt: now - 1000, updatedAt: now - 1000,
    ...Object.fromEntries(Object.entries(over).filter(([k]) =>
      !['id', 'params', 'stage', 'taskIds', 'artifactId', 'artifactPreview', 'caption'].includes(k))),
  }
}

/** 워크플로 목록을 통째로 갈아 끼우고 저장소를 다시 읽힌다. */
function seed(list) {
  fs.writeFileSync(WF_FILE, JSON.stringify({ version: 1, workflows: list, grant: null }), 'utf8')
  W.initSocialWorkflows()
}

// ===================== ① 정상 초안은 확인 화면이 열린다 =====================

seed([wf()])
const p1 = W.preparePromotion('wf1')
t('확인 단계 초안이면 확정 화면이 열린다', p1.ok === true, JSON.stringify(p1).slice(0, 300))
t('확정 화면이 보여 주는 이미지 지문이 **실제 보관 파일의 sha256** 과 같다',
  p1.ok && p1.plan.artifactSha256 === ART.sha256, `plan=${p1.ok ? p1.plan.artifactSha256 : 'n/a'} art=${ART.sha256}`)
t('확정 화면이 목적지·계정·캡션을 그대로 보여 준다',
  p1.ok && p1.plan.platform === 'instagram' && p1.plan.account === 'me' && p1.plan.caption === '오늘의 사진입니다',
  JSON.stringify(p1.ok ? p1.plan : {}).slice(0, 300))
t('확정 화면에 한국어·영어 플랫폼 이름이 함께 있다',
  p1.ok && !!p1.plan.platformLabel && !!p1.plan.platformLabelEn && p1.plan.platformLabel !== p1.plan.platformLabelEn,
  JSON.stringify(p1.ok ? [p1.plan.platformLabel, p1.plan.platformLabelEn] : []))
t('확정 화면을 여는 것만으로는 승격이 기록되지 않는다(디스크·메모리 둘 다)',
  !W.getWorkflow('wf1').promotedAt && !JSON.parse(fs.readFileSync(WF_FILE, 'utf8')).workflows[0].promotedAt)

// 취소는 **아무것도 바꾸지 않는다**.
const beforeCancel = JSON.stringify(W.getWorkflow('wf1'))
W.cancelPromotion('wf1')
t('취소하면 워크플로가 한 글자도 바뀌지 않는다', JSON.stringify(W.getWorkflow('wf1')) === beforeCancel)
t('취소한 뒤에는 그 확인으로 게시할 수 없다',
  rejected(W.confirmPromotion('wf1', p1.ok ? p1.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))

// ===================== ② 확인은 1회용이다 =====================

seed([wf()])
const p2 = W.preparePromotion('wf1')
t('틀린 토큰으로는 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', 'wrong-token'), '확인 정보가 맞지 않아', 'did not match'))
t('틀린 토큰 한 번으로 그 확인은 소진된다 — 곧이어 맞는 토큰을 보내도 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', p2.ok ? p2.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))
t('그 사이에도 승격 기록은 생기지 않았다', !W.getWorkflow('wf1').promotedAt)

// 만료
seed([wf()])
const p2b = W.preparePromotion('wf1')
t('오래된 확인은 만료된다',
  (() => {
    const realNow = Date.now
    Date.now = () => realNow() + 11 * 60_000   // TTL 10분
    try { return rejected(W.confirmPromotion('wf1', p2b.ok ? p2b.plan.token : 'x'), '만료', 'expired') }
    finally { Date.now = realNow }
  })())

// ===================== ③ 확인한 것과 달라지면 무효다 =====================

seed([wf()])
const p3 = W.preparePromotion('wf1')
W.setCaption('wf1', '완전히 다른 캡션')
const r3 = W.confirmPromotion('wf1', p3.ok ? p3.plan.token : 'x')
t('확인 뒤 캡션이 바뀌면 그 확인으로 게시하지 않는다', r3.ok === false, JSON.stringify(r3).slice(0, 300))
t('바뀐 것이 캡션이라고 사람 말로 알려 준다(ko·en)',
  typeof r3.error === 'string' && r3.error.includes('캡션')
  && typeof r3.errorEn === 'string' && r3.errorEn.includes('caption'),
  JSON.stringify(r3).slice(0, 300))
t('캡션을 바꾼 것만으로 게시가 나가지 않았다', !W.getWorkflow('wf1').promotedAt && !W.getWorkflow('wf1').taskIds.publish)

seed([wf()])
const p4 = W.preparePromotion('wf1')
W.setWorkflowAccount('wf1', 'someone-else')
const r4 = W.confirmPromotion('wf1', p4.ok ? p4.plan.token : 'x')
t('확인 뒤 계정이 바뀌면 그 확인으로 게시하지 않는다', r4.ok === false, JSON.stringify(r4).slice(0, 300))
t('바뀐 것이 계정이라고 사람 말로 알려 준다(ko·en)',
  typeof r4.error === 'string' && r4.error.includes('계정')
  && typeof r4.errorEn === 'string' && r4.errorEn.includes('account'),
  JSON.stringify(r4).slice(0, 300))

// 바인딩 지문 자체가 그 사실들로 갈리는가 — 같은 내용이면 같고, 한 글자만 달라도 다르다.
seed([wf()])
const revA = W.preparePromotion('wf1').plan.revision
seed([wf()])
const revA2 = W.preparePromotion('wf1').plan.revision
seed([wf({ caption: '오늘의 사진입니다!' })])
const revB = W.preparePromotion('wf1').plan.revision
seed([wf({ params: { account: 'other' } })])
const revC = W.preparePromotion('wf1').plan.revision
t('같은 내용이면 바인딩 지문이 같고, 캡션·계정이 다르면 달라진다',
  revA === revA2 && revA !== revB && revA !== revC && revB !== revC,
  `A=${revA.slice(0, 8)} A2=${revA2.slice(0, 8)} B=${revB.slice(0, 8)} C=${revC.slice(0, 8)}`)

// ===================== ④ 올리면 안 되는 것은 거부한다 =====================

const denied = [
  ['계정이 없으면 거부한다', wf({ params: { account: undefined } }), '계정이 비어 있습니다', 'No account'],
  ['캡션이 비어 있으면 거부한다', wf({ caption: '   ' }), '캡션이 비어 있습니다', 'caption is empty'],
  ['캡션을 쓰는 중이면 거부한다', wf({ captionPending: true }), '캡션을 쓰는 중', 'still being drafted'],
  ['캡션 생성이 실패한 상태면 거부한다', wf({ captionError: '실패' }), '캡션을 만들지 못한', 'failed to generate'],
  ['처음부터 게시 모드였던 작업은 이 경로로 올리지 않는다', wf({ params: { mode: 'publish' } }), '초안이 아니라', 'publish mode'],
  ['이미 승격한 초안은 다시 올리지 않는다', wf({ promotedAt: Date.now() - 1 }), '이미 게시로 올린 초안', 'already been promoted'],
  ['게시 여부가 불확실하면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, publishUncertain: true, taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['게시 여부 확인 작업이 도는 중이면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, verifyTaskId: 'task_verify', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['생성 중인 작업은 거부한다', wf({ stage: 'generate' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['게시 중인 작업은 거부한다', wf({ stage: 'publish', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['실패한 작업은 거부한다', wf({ stage: 'failed' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['취소된 작업은 거부한다', wf({ stage: 'cancelled' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['이미 실제로 게시된 작업은 거부한다', wf({ stage: 'done', receipt: { status: 'verified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed a real publication'],
  ['사용자가 "이미 게시됨" 으로 결론 낸 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'user-confirmed', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['게시 여부 미확인으로 끝난 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'unverified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['status 가 없는 예전 영수증은 초안으로 치지 않는다(fail-closed)', wf({ stage: 'done', receipt: { evidence: '초안까지 준비(게시 안 함)', at: 1 } }), '예전 판본이라', 'predates'],
  ['지난 기록에 실제 게시가 있으면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 2 }, priorReceipts: [{ status: 'verified', at: 1 }] }), '이미 실제 게시 기록', 'already has a real publication'],
  ['보관 이미지가 없으면 거부한다', wf({ artifactId: 'art_doesnotexist' }), '보관된 이미지 파일을 찾을 수 없습니다', 'stored image file is gone'],
  ['생성 작업 기록이 없으면 거부한다', wf({ taskIds: {} }), '올릴 이미지 기록이 없습니다', 'No stored image'],
  ['보관 이미지가 처음 확인한 것과 다르면 거부한다', wf({ artifactPreview: { bytes: 1, format: 'png', sha256: 'deadbeef' } }), '처음 확인한 것과 달라졌습니다', 'no longer matches'],
]

for (const [name, record, ko, en] of denied) {
  seed([record])
  const pr = W.preparePromotion(record.id ?? 'wf1')
  const cf = W.confirmPromotion(record.id ?? 'wf1', 'any-token')
  // prepare 가 거부하고, 확인 화면을 건너뛰고 직접 confirm 을 불러도 거부한다(UI 를 믿지 않는다).
  t(name, rejected(pr, ko, en) && cf.ok === false, `prepare=${JSON.stringify(pr).slice(0, 220)} confirm=${JSON.stringify(cf).slice(0, 160)}`)
  // 거부는 **초안을 잃지 않는다** — 캡션·이미지·단계가 그대로 남아야 사용자가 고쳐서 다시 쓴다.
  const after = W.getWorkflow(record.id ?? 'wf1')
  t(`  └ 거부해도 초안이 그대로 남는다 — ${name}`,
    !!after && after.stage === record.stage && after.caption === record.caption
    && after.artifactId === record.artifactId && !after.promotedAt,
    JSON.stringify(after ?? {}).slice(0, 200))
}

// ===================== ⑤ 완료된 초안은 올릴 수 있다 =====================

seed([wf({
  stage: 'done',
  taskIds: { generate: GEN_TASK, publish: 'task_pub_draft' },
  receipt: { status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 1234 },
})])
const p5 = W.preparePromotion('wf1')
t('완료된 초안(영수증 status=draft)은 확정 화면이 열린다', p5.ok === true, JSON.stringify(p5).slice(0, 300))
t('그 확정 화면은 "완료된 초안에서 올린다" 고 표시한다', p5.ok && p5.plan.source === 'completed-draft', p5.ok ? p5.plan.source : 'n/a')

// ===================== ⑥ 승격 작업은 자동 게시 대상이 아니다 =====================

const g = W.grantAutoPublish({ platform: 'instagram', accounts: ['me'], maxPosts: 5, minutes: 60 })
t('선승인 자체는 만들어진다(대조군)', !!g)
const promoted = wf({ params: { mode: 'publish' }, promotedAt: Date.now(), createdAt: Date.now() })
promoted.createdAt = Date.now() + 1000   // 선승인보다 나중에 만들어진 것으로
const verdict = W.autoPublishVerdict(promoted)
t('사용자가 직접 확정해 올린 초안은 선승인이 있어도 자동 게시되지 않는다',
  verdict.ok === false && verdict.why.includes('직접 확정'), JSON.stringify(verdict))
W.revokeAutoPublish()

// ===================== ⑦ 재시작을 넘겨 기억한다 =====================

const priors = [{ status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 111, taskId: 'task_pub_draft', note: '초안 준비 기록' }]
seed([wf({ stage: 'done', promotedAt: 4242, priorReceipts: priors, receipt: { status: 'verified', at: 999 } })])
const restored = W.getWorkflow('wf1')
t('승격 사실이 재시작을 넘겨 남는다', restored.promotedAt === 4242, String(restored.promotedAt))
t('지난 초안 기록이 재시작을 넘겨 그대로 남는다',
  restored.priorReceipts?.length === 1 && restored.priorReceipts[0].status === 'draft'
  && restored.priorReceipts[0].at === 111 && restored.priorReceipts[0].taskId === 'task_pub_draft',
  JSON.stringify(restored.priorReceipts))

// 손상된 값 — **잊는 쪽이 위험하다**(잊으면 실제 게시가 "초안" 으로 적히고 또 올릴 수 있게 된다).
seed([wf({ stage: 'done', promotedAt: 'garbage', receipt: { status: 'verified', at: 1 } })])
t('승격 값이 손상돼도 "승격했다" 로 기억한다(fail-closed)', W.getWorkflow('wf1').promotedAt === 1,
  String(W.getWorkflow('wf1').promotedAt))
seed([wf({ stage: 'done', priorReceipts: 'not-an-array', receipt: { status: 'draft', at: 1 } })])
t('지난 기록이 손상됐으면 조용히 버리고 워크플로 자체는 살린다',
  !!W.getWorkflow('wf1') && !W.getWorkflow('wf1').priorReceipts)

// ===================== 마무리 =====================

const outDir = path.join(REPO, 'verify-out', 'draft-promotion-pure')
fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, 'results.json'),
  JSON.stringify({ at: new Date().toISOString(), pass, fail, results }, null, 2), 'utf8')

try { fs.rmSync(root, { recursive: true, force: true }) } catch { /* 임시 디렉터리 정리 실패는 무시 */ }

console.log(`\n초안 승격 게이트: ${pass} PASS / ${fail} FAIL`)
console.log('범위: 판정 규칙만(앱 없이). 실제 게시 흐름은 build/verify-draft-promotion-cdp.mjs 가 본다.')
process.exit(fail === 0 ? 0 : 1)

tool_use_result.content:
// 초안 승격(draft promotion) **게이트 판정** 검증 — 앱 없이 도는 순수 검사.
//
// 무엇을 지키는가: "만들어 둔 초안을 다시 만들지 않고 게시로 올린다" 는 편의 기능이지만, 그 끝에
// 있는 것은 **되돌릴 수 없는 외부 게시**다. 그래서 이 판정이 지켜야 하는 것은 둘이다.
//
//   ① 올려도 되는 것만 올린다 — 이미 게시된 것·게시 중인 것·나갔는지 모르는 것·계정이 없는 것·
//      이미지가 사라진 것은 거부한다.
//   ② 사용자가 **확인한 그것**만 올린다 — 확인 뒤에 캡션·계정·이미지가 바뀌었으면 그 확인은 무효다.
//      확인은 1회용이라 연타·재전송으로 두 번 나가지 않는다.
//
// 이 파일이 보증하는 것: 위 판정 규칙(거부 경로 전부 + 확인의 바인딩·1회용).
// 이 파일이 보증하지 **않는** 것: 실제 게시 흐름(작업 생성·산출물 복사·업로드·영수증). 그것은
//   build/verify-draft-promotion-cdp.mjs 가 실제 앱 + 실제 UI 클릭 + 로컬 픽스처로 검증한다.
//   여기서는 **성공 경로의 confirm 을 일부러 부르지 않는다** — 부르면 실제 게시 단계가 시작된다.
//
// 선례: build/verify-auto-publish.mjs (같은 electron 스텁 방식 · 같은 양방향 판정 원칙).

import path from 'node:path'
import fs from 'node:fs'
import os from 'node:os'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const require = createRequire(import.meta.url)
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-promote-'))

// social-workflow 는 electron(app) 과 설정을 끌어온다 — 파일 경로만 임시 디렉터리로 돌려주면 충분하다.
const Module = require('module')
const origLoad = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return {
      app: {
        getPath: () => root,
        getVersion: () => '0.0.0-test',
        getName: () => 'ezbrowser-test',
        on: () => {}, whenReady: () => Promise.resolve(), isPackaged: false,
      },
      ipcMain: { handle: () => {}, on: () => {} },
      safeStorage: { isEncryptionAvailable: () => false },
    }
  }
  return origLoad.call(this, req, ...rest)
}

const W = require(path.join(REPO, 'app/dist/main/features/ai/social-workflow.js'))
const A = require(path.join(REPO, 'app/dist/main/features/ai/artifacts.js'))

let pass = 0, fail = 0
const results = []
const t = (name, cond, detail = '') => {
  if (cond) { pass++; console.log('  PASS', name) } else { fail++; console.log('  FAIL', name, detail) }
  results.push({ name, ok: !!cond, detail: cond ? '' : String(detail).slice(0, 400) })
}

/** 거부는 **한국어와 영어를 함께** 줘야 한다(화면이 둘 다 보인다). 통과 여부와 같이 본다. */
const rejected = (r, koNeedle, enNeedle) =>
  r && r.ok === false
  && typeof r.error === 'string' && r.error.includes(koNeedle)
  && typeof r.errorEn === 'string' && r.errorEn.toLowerCase().includes(enNeedle.toLowerCase())

// ───────────────────────── 진짜 산출물 만들기 ─────────────────────────
// 1×1 PNG — importDownloadedFile 이 이미지 매직바이트를 확인하므로 진짜 PNG 여야 한다.
const PNG_1X1 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64')

const GEN_TASK = 'task_gen_promotion'
const tmpPng = path.join(root, 'seed.png')
fs.writeFileSync(tmpPng, PNG_1X1)
const imported = A.importDownloadedFile({
  taskId: GEN_TASK, filePath: tmpPng,
  sourceUrl: 'http://127.0.0.1/gen.png', sourcePageUrl: 'http://127.0.0.1/gen', sourceTabId: 'tab1',
  expect: 'image', label: '테스트 산출물',
})
if (!imported.ok || !imported.meta) {
  console.error('FATAL: 테스트 산출물을 만들지 못했습니다 —', imported.error ?? imported.code)
  process.exit(2)
}
const ART = imported.meta

// ───────────────────────── 워크플로 시드 ─────────────────────────
// 저장 파일을 직접 써 두고 initSocialWorkflows 로 읽힌다(하네스 관례: 실제 복원 경로를 지난다).
const WF_FILE = path.join(root, 'ai-social-workflows.json')

function wf(over = {}) {
  const now = Date.now()
  return {
    id: over.id ?? 'wf1',
    params: {
      service: 'genspark', platform: 'instagram', prompt: '테스트 프롬프트',
      mode: 'draft', tabId: 'tab1', windowId: 'win1', account: 'me',
      ...(over.params ?? {}),
    },
    stage: over.stage ?? 'review',
    taskIds: over.taskIds ?? { generate: GEN_TASK },
    artifactId: 'artifactId' in over ? over.artifactId : ART.id,
    artifactPreview: 'artifactPreview' in over ? over.artifactPreview
      : { bytes: ART.bytes, format: ART.format, sha256: ART.sha256 },
    caption: 'caption' in over ? over.caption : '오늘의 사진입니다',
    createdAt: now - 1000, updatedAt: now - 1000,
    ...Object.fromEntries(Object.entries(over).filter(([k]) =>
      !['id', 'params', 'stage', 'taskIds', 'artifactId', 'artifactPreview', 'caption'].includes(k))),
  }
}

/** 워크플로 목록을 통째로 갈아 끼우고 저장소를 다시 읽힌다. */
function seed(list) {
  fs.writeFileSync(WF_FILE, JSON.stringify({ version: 1, workflows: list, grant: null }), 'utf8')
  W.initSocialWorkflows()
}

// ===================== ① 정상 초안은 확인 화면이 열린다 =====================

seed([wf()])
const p1 = W.preparePromotion('wf1')
t('확인 단계 초안이면 확정 화면이 열린다', p1.ok === true, JSON.stringify(p1).slice(0, 300))
t('확정 화면이 보여 주는 이미지 지문이 **실제 보관 파일의 sha256** 과 같다',
  p1.ok && p1.plan.artifactSha256 === ART.sha256, `plan=${p1.ok ? p1.plan.artifactSha256 : 'n/a'} art=${ART.sha256}`)
t('확정 화면이 목적지·계정·캡션을 그대로 보여 준다',
  p1.ok && p1.plan.platform === 'instagram' && p1.plan.account === 'me' && p1.plan.caption === '오늘의 사진입니다',
  JSON.stringify(p1.ok ? p1.plan : {}).slice(0, 300))
t('확정 화면에 한국어·영어 플랫폼 이름이 함께 있다',
  p1.ok && !!p1.plan.platformLabel && !!p1.plan.platformLabelEn && p1.plan.platformLabel !== p1.plan.platformLabelEn,
  JSON.stringify(p1.ok ? [p1.plan.platformLabel, p1.plan.platformLabelEn] : []))
t('확정 화면을 여는 것만으로는 승격이 기록되지 않는다(디스크·메모리 둘 다)',
  !W.getWorkflow('wf1').promotedAt && !JSON.parse(fs.readFileSync(WF_FILE, 'utf8')).workflows[0].promotedAt)

// 취소는 **아무것도 바꾸지 않는다**.
const beforeCancel = JSON.stringify(W.getWorkflow('wf1'))
W.cancelPromotion('wf1')
t('취소하면 워크플로가 한 글자도 바뀌지 않는다', JSON.stringify(W.getWorkflow('wf1')) === beforeCancel)
t('취소한 뒤에는 그 확인으로 게시할 수 없다',
  rejected(W.confirmPromotion('wf1', p1.ok ? p1.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))

// ===================== ② 확인은 1회용이다 =====================

seed([wf()])
const p2 = W.preparePromotion('wf1')
t('틀린 토큰으로는 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', 'wrong-token'), '확인 정보가 맞지 않아', 'did not match'))
t('틀린 토큰 한 번으로 그 확인은 소진된다 — 곧이어 맞는 토큰을 보내도 게시하지 않는다',
  rejected(W.confirmPromotion('wf1', p2.ok ? p2.plan.token : 'x'), '유효한 확인이 없습니다', 'No valid confirmation'))
t('그 사이에도 승격 기록은 생기지 않았다', !W.getWorkflow('wf1').promotedAt)

// 만료
seed([wf()])
const p2b = W.preparePromotion('wf1')
t('오래된 확인은 만료된다',
  (() => {
    const realNow = Date.now
    Date.now = () => realNow() + 11 * 60_000   // TTL 10분
    try { return rejected(W.confirmPromotion('wf1', p2b.ok ? p2b.plan.token : 'x'), '만료', 'expired') }
    finally { Date.now = realNow }
  })())

// ===================== ③ 확인한 것과 달라지면 무효다 =====================

seed([wf()])
const p3 = W.preparePromotion('wf1')
W.setCaption('wf1', '완전히 다른 캡션')
const r3 = W.confirmPromotion('wf1', p3.ok ? p3.plan.token : 'x')
t('확인 뒤 캡션이 바뀌면 그 확인으로 게시하지 않는다', r3.ok === false, JSON.stringify(r3).slice(0, 300))
t('바뀐 것이 캡션이라고 사람 말로 알려 준다(ko·en)',
  typeof r3.error === 'string' && r3.error.includes('캡션')
  && typeof r3.errorEn === 'string' && r3.errorEn.includes('caption'),
  JSON.stringify(r3).slice(0, 300))
t('캡션을 바꾼 것만으로 게시가 나가지 않았다', !W.getWorkflow('wf1').promotedAt && !W.getWorkflow('wf1').taskIds.publish)

seed([wf()])
const p4 = W.preparePromotion('wf1')
W.setWorkflowAccount('wf1', 'someone-else')
const r4 = W.confirmPromotion('wf1', p4.ok ? p4.plan.token : 'x')
t('확인 뒤 계정이 바뀌면 그 확인으로 게시하지 않는다', r4.ok === false, JSON.stringify(r4).slice(0, 300))
t('바뀐 것이 계정이라고 사람 말로 알려 준다(ko·en)',
  typeof r4.error === 'string' && r4.error.includes('계정')
  && typeof r4.errorEn === 'string' && r4.errorEn.includes('account'),
  JSON.stringify(r4).slice(0, 300))

// 바인딩 지문 자체가 그 사실들로 갈리는가 — 같은 내용이면 같고, 한 글자만 달라도 다르다.
seed([wf()])
const revA = W.preparePromotion('wf1').plan.revision
seed([wf()])
const revA2 = W.preparePromotion('wf1').plan.revision
seed([wf({ caption: '오늘의 사진입니다!' })])
const revB = W.preparePromotion('wf1').plan.revision
seed([wf({ params: { account: 'other' } })])
const revC = W.preparePromotion('wf1').plan.revision
t('같은 내용이면 바인딩 지문이 같고, 캡션·계정이 다르면 달라진다',
  revA === revA2 && revA !== revB && revA !== revC && revB !== revC,
  `A=${revA.slice(0, 8)} A2=${revA2.slice(0, 8)} B=${revB.slice(0, 8)} C=${revC.slice(0, 8)}`)

// ===================== ④ 올리면 안 되는 것은 거부한다 =====================

const denied = [
  ['계정이 없으면 거부한다', wf({ params: { account: undefined } }), '계정이 비어 있습니다', 'No account'],
  ['캡션이 비어 있으면 거부한다', wf({ caption: '   ' }), '캡션이 비어 있습니다', 'caption is empty'],
  ['캡션을 쓰는 중이면 거부한다', wf({ captionPending: true }), '캡션을 쓰는 중', 'still being drafted'],
  ['캡션 생성이 실패한 상태면 거부한다', wf({ captionError: '실패' }), '캡션을 만들지 못한', 'failed to generate'],
  ['처음부터 게시 모드였던 작업은 이 경로로 올리지 않는다', wf({ params: { mode: 'publish' } }), '초안이 아니라', 'publish mode'],
  ['이미 승격한 초안은 다시 올리지 않는다', wf({ promotedAt: Date.now() - 1 }), '이미 게시로 올린 초안', 'already been promoted'],
  ['게시 여부가 불확실하면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, publishUncertain: true, taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['게시 여부 확인 작업이 도는 중이면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 1 }, verifyTaskId: 'task_verify', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '게시 여부가 확인되지 않아', 'unresolved'],
  ['생성 중인 작업은 거부한다', wf({ stage: 'generate' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['게시 중인 작업은 거부한다', wf({ stage: 'publish', taskIds: { generate: GEN_TASK, publish: 'task_pub' } }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['실패한 작업은 거부한다', wf({ stage: 'failed' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['취소된 작업은 거부한다', wf({ stage: 'cancelled' }), '올릴 수 있는 단계가 아닙니다', 'Not in a promotable state'],
  ['이미 실제로 게시된 작업은 거부한다', wf({ stage: 'done', receipt: { status: 'verified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed a real publication'],
  ['사용자가 "이미 게시됨" 으로 결론 낸 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'user-confirmed', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['게시 여부 미확인으로 끝난 작업도 거부한다', wf({ stage: 'done', receipt: { status: 'unverified', at: 1 } }), '이미 게시까지 끝났습니다', 'already completed'],
  ['status 가 없는 예전 영수증은 초안으로 치지 않는다(fail-closed)', wf({ stage: 'done', receipt: { evidence: '초안까지 준비(게시 안 함)', at: 1 } }), '예전 판본이라', 'predates'],
  ['지난 기록에 실제 게시가 있으면 거부한다', wf({ stage: 'done', receipt: { status: 'draft', at: 2 }, priorReceipts: [{ status: 'verified', at: 1 }] }), '이미 실제 게시 기록', 'already has a real publication'],
  ['보관 이미지가 없으면 거부한다', wf({ artifactId: 'art_doesnotexist' }), '보관된 이미지 파일을 찾을 수 없습니다', 'stored image file is gone'],
  ['생성 작업 기록이 없으면 거부한다', wf({ taskIds: {} }), '올릴 이미지 기록이 없습니다', 'No stored image'],
  ['보관 이미지가 처음 확인한 것과 다르면 거부한다', wf({ artifactPreview: { bytes: 1, format: 'png', sha256: 'deadbeef' } }), '처음 확인한 것과 달라졌습니다', 'no longer matches'],
]

for (const [name, record, ko, en] of denied) {
  seed([record])
  const pr = W.preparePromotion(record.id ?? 'wf1')
  const cf = W.confirmPromotion(record.id ?? 'wf1', 'any-token')
  // prepare 가 거부하고, 확인 화면을 건너뛰고 직접 confirm 을 불러도 거부한다(UI 를 믿지 않는다).
  t(name, rejected(pr, ko, en) && cf.ok === false, `prepare=${JSON.stringify(pr).slice(0, 220)} confirm=${JSON.stringify(cf).slice(0, 160)}`)
  // 거부는 **초안을 잃지 않는다** — 캡션·이미지·단계가 그대로 남아야 사용자가 고쳐서 다시 쓴다.
  const after = W.getWorkflow(record.id ?? 'wf1')
  t(`  └ 거부해도 초안이 그대로 남는다 — ${name}`,
    !!after && after.stage === record.stage && after.caption === record.caption
    && after.artifactId === record.artifactId && !after.promotedAt,
    JSON.stringify(after ?? {}).slice(0, 200))
}

// ===================== ⑤ 완료된 초안은 올릴 수 있다 =====================

seed([wf({
  stage: 'done',
  taskIds: { generate: GEN_TASK, publish: 'task_pub_draft' },
  receipt: { status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 1234 },
})])
const p5 = W.preparePromotion('wf1')
t('완료된 초안(영수증 status=draft)은 확정 화면이 열린다', p5.ok === true, JSON.stringify(p5).slice(0, 300))
t('그 확정 화면은 "완료된 초안에서 올린다" 고 표시한다', p5.ok && p5.plan.source === 'completed-draft', p5.ok ? p5.plan.source : 'n/a')

// ===================== ⑥ 승격 작업은 자동 게시 대상이 아니다 =====================

const g = W.grantAutoPublish({ platform: 'instagram', accounts: ['me'], maxPosts: 5, minutes: 60 })
t('선승인 자체는 만들어진다(대조군)', !!g)
const promoted = wf({ params: { mode: 'publish' }, promotedAt: Date.now(), createdAt: Date.now() })
promoted.createdAt = Date.now() + 1000   // 선승인보다 나중에 만들어진 것으로
const verdict = W.autoPublishVerdict(promoted)
t('사용자가 직접 확정해 올린 초안은 선승인이 있어도 자동 게시되지 않는다',
  verdict.ok === false && verdict.why.includes('직접 확정'), JSON.stringify(verdict))
W.revokeAutoPublish()

// ===================== ⑦ 재시작을 넘겨 기억한다 =====================

const priors = [{ status: 'draft', evidence: '초안까지 준비(게시 안 함)', at: 111, taskId: 'task_pub_draft', note: '초안 준비 기록' }]
seed([wf({ stage: 'done', promotedAt: 4242, priorReceipts: priors, receipt: { status: 'verified', at: 999 } })])
const restored = W.getWorkflow('wf1')
t('승격 사실이 재시작을 넘겨 남는다', restored.promotedAt === 4242, String(restored.promotedAt))
t('지난 초안 기록이 재시작을 넘겨 그대로 남는다',
  restored.priorReceipts?.length === 1 && restored.priorReceipts[0].status === 'draft'
  && restored.priorReceipts[0].at === 111 && restored.priorReceipts[0].taskId === 'task_pub_draft',
  JSON.stringify(restored.priorReceipts))

// 손상된 값 — **잊는 쪽이 위험하다**(잊으면 실제 게시가 "초안" 으로 적히고 또 올릴 수 있게 된다).
seed([wf({ stage: 'done', promotedAt: 'garbage', receipt: { status: 'verified', at: 1 } })])
t('승격 값이 손상돼도 "승격했다" 로 기억한다(fail-closed)', W.getWorkflow('wf1').promotedAt === 1,
  String(W.getWorkflow('wf1').promotedAt))
seed([wf({ stage: 'done', priorReceipts: 'not-an-array', receipt: { status: 'draft', at: 1 } })])
t('지난 기록이 손상됐으면 조용히 버리고 워크플로 자체는 살린다',
  !!W.getWorkflow('wf1') && !W.getWorkflow('wf1').priorReceipts)

// ===================== 마무리 =====================

const outDir = path.join(REPO, 'verify-out', 'draft-promotion-pure')
fs.mkdirSync(outDir, { recursive: true })
fs.writeFileSync(path.join(outDir, 'results.json'),
  JSON.stringify({ at: new Date().toISOString(), pass, fail, results }, null, 2), 'utf8')

try { fs.rmSync(root, { recursive: true, force: true }) } catch { /* 임시 디렉터리 정리 실패는 무시 */ }

console.log(`\n초안 승격 게이트: ${pass} PASS / ${fail} FAIL`)
console.log('범위: 판정 규칙만(앱 없이). 실제 게시 흐름은 build/verify-draft-promotion-cdp.mjs 가 본다.')
process.exit(fail === 0 ? 0 : 1)

