    [['게시 여부가 확인되지 않아', 'unresolved']]],
  ['d-generating', '생성 중인 작업은 거부한다', wf('d-generating', { stage: 'generate' }), [['올릴 수 있는 단계가 아닙니다', 'Not in a promotable state']]],
