// 열린 확정 패널이 낡아지면(승격됐거나, 계획을 딸 때의 단계에서 벗어났으면) 자동으로 닫는다 —
// 사용자가 이미 처리된(혹은 더는 유효하지 않은) 계획을 보며 게시 확정을 누르는 일을 막는다.
useEffect(() => {
  setPromotions((prev) => {
    if (Object.keys(prev).length === 0) return prev
    let changed = false
    const next = { ...prev }
    for (const w of workflows) {
      const plan = next[w.id]
      if (!plan) continue
      const expectedStage: SocialStage = plan.source === 'review' ? 'review' : 'done'
      if (w.promotedAt || w.stage !== expectedStage) {
        delete next[w.id]
        changed = true
      }
    }
    return changed ? next : prev
  })
}, [workflows])

