    return {
      found: true,
      hasPromoteBtn: !!c.querySelector('.ai-social-promote'),
      hasPanel: !!panel,
      revision: panel ? panel.getAttribute('data-revision') : null,
      hasError: !!err,
      errorText: err ? err.textContent.trim() : null,
    }
  })()`)
}
