1464	  // 기존 게시 경로를 그대로 탄다 — 게이트·내구성 경계·이어가기 보호를 재사용한다.
1465	  // 탭 이동(비동기) 중에 실패하면 그때도 같은 되돌리기를 쓴다 — 그 구간에서는 아직 게시 작업이
1466	  // 만들어지지 않았으므로 되돌려도 안전하다(runPublishStage 주석: "그 구간의 결과는 게시 0건").
1467	  const r = runPublishStage(wf, subject.genTaskId, subject.artifactId, { onAbort: rollback })
1468	  if (!r.ok) {
1469	    rollback()
1470	    return { ok: false, error: r.error ?? '게시를 시작하지 못했습니다.', errorEn: r.error ?? 'Failed to start publishing.' }
1471	  }
1472	  return { ok: true }
1473	}
1474	
1475	/**
1476	 * 이 워크플로가 **지금** 실제로 게시하는가. 처음 고른 모드(params.mode)에, 사용자가 나중에 초안을
1477	 * 올리겠다고 확정한 사실(promotedAt)을 더한 값이다. 게시 작업을 만들 때와 영수증을 적을 때 **둘 다**
1478	 * 이 함수를 써야 한다 — 한쪽만 쓰면 실제로는 게시했는데 영수증이 "초안" 이라고 적히는 식으로 어긋난다.
1479	 */
