  actualSha = createHash('sha256').update(readFileSync(srcPath)).digest('hex')
} catch {
  return rejectPromotion(
    '보관된 이미지 파일을 읽을 수 없습니다 — 초안은 그대로 남아 있습니다.',
    'The stored image file could not be read — the draft itself is intact.')
