const STAGE_LABEL: Record<string, string> = {
  generate: '이미지 생성 중', review: '확인', publish: '게시 중',
  done: '완료', failed: '실패', cancelled: '취소됨',
}
// ⚠ WorkflowRecovery['kind'] 에 값을 추가하면 **여기도** 넓혀야 한다. Set 은 부분집합도 허용하므로
