await dbg.sendCommand('DOM.setFileInputFiles', { files: filePaths, nodeId: best.nodeId }, best.sessionId)

// ⚠ 첨부만으로는 **페이지가 그 사실을 모른다.** `DOM.setFileInputFiles` 는 input.files 를 채우지만
//   `input`/`change` 이벤트를 쏘지 않는다 — Puppeteer 도 같은 이유로 첨부 뒤 직접 이벤트를 쏜다.
//
//   실제로 무슨 일이 벌어지는가 (2026-09-19 하네스가 잡았다): 인스타·유튜브·틱톡의 업로드 화면은
//   전부 `change` 를 듣고 "다음" 버튼의 disabled 를 푼다. 이벤트가 없으면 파일은 붙었는데 다음
//   버튼이 영원히 잠긴 채라, 에이전트는 "첨부됨" 이라고 보고하고도 **한 발짝도 나아가지 못한다.**
//   (검증 픽스처에서 위저드가 1단계에 멈춘 채 6번의 관찰이 똑같이 반복되는 것으로 드러났다.)
//
//   같은 김에 **정말 붙었는지** 도 확인한다 — 첨부가 조용히 0개로 끝나는 것을 "성공" 이라 보고하면
//   빈 게시물이 올라간다(SEC-1 의 "무검증 성공 제거" 와 같은 원칙).
let landed = -1
let notified = false
try {
  const resolved = await dbg.sendCommand(
    'DOM.resolveNode', { nodeId: best.nodeId }, best.sessionId,
  ) as { object?: { objectId?: string } }
  const objectId = resolved?.object?.objectId
  if (objectId) {
    const r = await dbg.sendCommand('Runtime.callFunctionOn', {
      objectId,
      functionDeclaration: `function () {
        try {
          this.dispatchEvent(new Event('input', { bubbles: true, composed: true }));
          this.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
        } catch (e) { /* 이벤트 생성 실패는 아래 개수로 판단한다 */ }
        return this.files ? this.files.length : -1;
      }`,
      returnByValue: true,
    }, best.sessionId) as { result?: { value?: number } }
